from lib import *

L4 = lesson('4강. for 와 range — 누적의 기술', 25,
'- `range(a, b, c)`: a부터 **b 직전**까지 c씩. `range(n)` 은 0 ~ n-1\n- 누적 3종: 합 `total += x`, 개수 `cnt += 1`, 최대 `if x > best: best = x`\n- 누적 변수는 **반복문 밖에서 초기화**\n- 평균 = 합 / 개수, 리스트는 `for x in lst` 로 순회\n- 역순: `range(n, 0, -1)`',
review('🔁 2~3강 복습', [T('조건문과 나머지 연산을 섞어 볼게요.'), rev('`if` 를 두 번 쓰는 것과 `if-elif` 의 차이는?', '`if` 두 번은 **둘 다 검사**, `if-elif` 는 **처음 참인 하나만** 실행해요.'), rev('3의 배수이면서 짝수인지 검사하는 조건식은?', code='n % 3 == 0 and n % 2 == 0')]),
order('복습 — 점수로 등급을 출력하는 코드를 순서대로 놓으세요.', ['s = int(input())', 'if s >= 90:', '    print("A")', 'elif s >= 80:', '    print("B")', 'else:', '    print("C")'], stdin='85', review=True),
explain('range 완전 정복',
  [T('`for` 는 **정해진 횟수**만큼 반복해요. `range` 가 그 횟수와 값을 만들어요.'),
   tabs(['range(5)', '0부터 5 **직전**까지: 0 1 2 3 4', 'for i in range(5):\n    print(i, end=" ")'], ['range(2, 6)', '2부터 6 직전까지: 2 3 4 5', 'for i in range(2, 6):\n    print(i, end=" ")'], ['range(1, 10, 3)', '1부터 3씩: 1 4 7', 'for i in range(1, 10, 3):\n    print(i, end=" ")'], ['range(5, 0, -1)', '거꾸로: 5 4 3 2 1', 'for i in range(5, 0, -1):\n    print(i, end=" ")']),
   key('끝 값은 **포함되지 않아요**. 1부터 n까지는 `range(1, n + 1)`.')],
  [T('반복 횟수는 `(끝 - 시작)` 을 간격으로 나눠 올림한 값이에요.'),
   flip(['range(3, 8) 은 몇 번?', '5번 (3,4,5,6,7)'], ['range(10, 0, -2) 의 값은?', '10 8 6 4 2 (0 은 직전이라 제외)'], ['range(5, 2) 는?', '0번 — 간격이 +1 인데 시작이 더 커서 **한 번도 안 돌아요**'])]),
sh('`for i in range(4, 20, 4):` 는 몇 번 반복할까요?', 4, '4, 8, 12, 16 → 4번. 20 은 직전이라 빠져요.'),
outq('출력 결과는?', 'for i in range(9, 0, -3):\n    print(i, end=" ")\nprint()\nfor i in range(1, 4):\n    print(i * i, end=" ")'),
explain('누적 패턴 ① 합과 개수',
  [T('"반복하면서 모은다"가 누적이에요. **그릇(변수)을 먼저 0으로 만들고**, 반복하며 담아요.'),
   trace('total = 0\nfor i in range(1, 5):\n    total += i\nprint(total)', '1+2+3+4 가 쌓이는 모습'),
   warn('`total = 0` 을 for **안**에 쓰면 돌 때마다 0으로 초기화돼요. 가장 흔한 실수예요.')],
  [T('삼각수(2023): 1, 3, 6, 10 … n번째 삼각수는 1부터 n까지의 합이에요. 과정을 모두 출력하려면 **누적하면서 출력**해요.'),
   C('n = 5\ntotal = 0\nfor i in range(1, n + 1):\n    total += i\n    print(total, end=" ")'),
   exam('"조건에 맞는 것만" 세거나 더하는 문제는 for 안에 if 를 넣어요: `if i % 3 == 0: cnt += 1`')]),
fill('1부터 100까지 수 중 **7의 배수의 개수**와 **합**을 구해요.', 'cnt = 0\ntotal = 0\nfor i in range(1, ___):\n    if i % 7 ___ 0:\n        cnt += 1\n        total ___ i\nprint(cnt, total)', ['101', '==', '+='], expect='14 735'),
spot('1부터 5까지의 합(15)을 출력하려는 코드예요. **잘못된 줄**을 고르세요.', 'for i in range(1, 6):\n    total = 0\n    total += i\nprint(total)', 2, '`total = 0` 이 반복문 안에 있어서 매번 0으로 돌아가요. for 위로 올려야 해요. 지금은 5가 출력돼요.'),
explain('누적 패턴 ② 리스트 순회 · 평균 · 최댓값',
  [T('리스트는 `for x in 리스트` 로 값을 하나씩 꺼내요. 2025 1번이 "합과 평균을 for 로 구하기"였어요.'),
   C('scores = [80, 95, 70, 100]\ntotal = 0\nfor s in scores:\n    total += s\navg = total / len(scores)\nprint(total, avg)'),
   tip('`sum(scores)` 로도 되지만, 시험은 **"for 문을 사용하여"** 라는 조건을 자주 붙여요. 두 방법 모두 알아야 해요.')],
  [T('최댓값은 "지금까지의 1등"을 기억하면서 비교해요.'),
   trace('nums = [3, 9, 4, 12, 7]\nbest = nums[0]\nfor x in nums:\n    if x > best:\n        best = x\nprint(best)', 'best 가 바뀌는 순간을 보세요'),
   key('`best` 의 첫 값은 0 이 아니라 **리스트의 첫 원소**로 잡아요. 음수만 있는 리스트에서 0 으로 시작하면 틀려요.')],
  [T('위치(인덱스)가 필요하면 `range(len(리스트))` 로 돌아요.'),
   C('days = [3, 5, 2, 8]\nfor i in range(len(days)):\n    print(f"{i + 1}일차: {days[i]}시간")')]),
outq('출력 결과는?', 'data = [4, -2, 7, 0, 1]\ncnt = 0\ns = 0\nfor x in data:\n    if x > 0:\n        cnt += 1\n        s += x\nprint(cnt, s, s / cnt)'),
ch('`nums = [-5, -2, -9]` 의 최댓값을 구하려고 `best = 0` 으로 시작해 `if x > best: best = x` 를 반복했어요. 결과는?', ['-2', '0', '-9', '오류'], 2, '모든 원소가 0 보다 작아 한 번도 갱신되지 않아요. `best = nums[0]` 으로 시작해야 해요.'),
essay('"1부터 n까지 홀수의 합"을 구하는 코드에서 누적 변수 `total = 0` 을 for 문 **안**에 두면 어떤 결과가 나오는지, 그 이유와 함께 서술하세요.', '반복할 때마다 total 이 0 으로 다시 초기화되므로 이전까지 더한 값이 사라진다. 그래서 마지막 반복에서 더한 값(마지막 홀수) 하나만 남아 출력된다. 누적 변수는 반복문이 시작되기 전에 한 번만 초기화해야 한다.', ['매 반복마다 0 으로 초기화된다고 썼다', '마지막 값만 남는다고 썼다', '반복문 밖(앞)에서 초기화해야 한다고 썼다']),
prac('기출 유사 ① — 삼각수 줄 세우기', '정수 `n` 이 주어지면 1번째부터 n번째까지의 **삼각수**를 한 줄에 공백으로 구분해 출력하고, 둘째 줄에 그중 **짝수의 개수**를 출력하세요.\n\n(k번째 삼각수 = 1 + 2 + … + k)\n\n[조건] ○ for 문을 **한 번만** 사용할 것',
  'n = int(input())\ntotal = 0\ncnt = 0\nout = []\nfor i in range(1, n + 1):\n    total += i\n    out.append(str(total))\n    if total % 2 == 0:\n        cnt += 1\nprint(" ".join(out))\nprint(cnt)', ['5', '1', '8', '3', '20', '50'],
  hints=['누적하면서 바로 출력해요: `print(total, end=" ")`', '짝수 개수는 같은 for 안에서 `if total % 2 == 0` 으로 세요.', '첫 줄을 다 출력한 뒤 `print()` 로 줄을 바꾸는 걸 잊지 마세요.']),
prac('기출 유사 ② — 공부 시간 리포트', '일주일(7일) 동안의 공부 시간(분)이 한 줄에 주어져요.\n\n- 첫 줄: 합계와 평균 (평균은 소수 첫째 자리까지, 예: `60.0`)\n- 둘째 줄: 가장 많이 공부한 날의 **번호**(1~7)와 그 시간. 같은 값이 여러 날이면 **가장 빠른 날**\n- 셋째 줄: 평균보다 **많이** 공부한 날의 수\n\n[조건] ○ `sum`, `max` 를 쓰지 말고 for 문으로 구할 것',
  'a = list(map(int, input().split()))\ntotal = 0\nfor x in a:\n    total += x\navg = total / len(a)\nbi = 0\nfor i in range(len(a)):\n    if a[i] > a[bi]:\n        bi = i\ncnt = 0\nfor x in a:\n    if x > avg:\n        cnt += 1\nprint(total, f"{avg:.1f}")\nprint(bi + 1, a[bi])\nprint(cnt)',
  ['60 90 30 120 45 0 75', '10 10 10 10 10 10 10', '0 0 0 0 0 0 1', '100 200 200 50 0 30 10', '55 43 78 91 12 91 66', '1 2 3 4 5 6 7'],
  starter='a = list(map(int, input().split()))\n', hints=['합 → 평균 → 최댓값 위치 → 평균 초과 개수 순서로 for 를 나눠 써도 돼요.', '가장 빠른 날이 되려면 `>` 로 비교해요 (`>=` 면 늦은 날이 돼요).', '평균은 `f"{avg:.1f}"`']),
)

L5 = lesson('5강. while — 상태 변수·break·continue', 35,
'- `while 조건:` 조건이 참인 동안 반복 — **조건을 바꾸는 코드**가 꼭 있어야 함\n- `break` 즉시 탈출, `continue` 아래를 건너뛰고 조건 검사로\n- `continue` 앞에서 증가를 빼먹으면 **무한 루프**\n- 상태 변수: 횟수 `tries`, 잔액 `balance`, 깃발 `found`\n- 자릿수 반복: `while n > 0: d = n % 10; n //= 10`',
review('🔁 3~4강 복습', [T('누적 패턴을 떠올려요.'), rev('누적 변수는 어디서 초기화하나요?', '반복문 **밖(앞)** 에서 한 번만.'), rev('`range(1, n + 1)` 에서 `+ 1` 을 하는 이유는?', '끝 값은 포함되지 않기 때문이에요.')]),
outq('복습 — 출력 결과는?', 'total = 0\nfor i in range(1, 11):\n    if i % 3 == 0:\n        total += i\nprint(total)', review=True),
explain('while 의 기본 구조',
  [T('`for` 는 횟수가 정해졌을 때, `while` 은 **언제 끝날지 모를 때** 써요. "맞힐 때까지", "잔액이 남아 있는 동안"처럼요.'),
   trace('n = 1\nwhile n < 20:\n    n = n * 2\nprint(n)', '조건 검사 → 실행 → 다시 조건 검사'),
   key('while 은 ① 조건 검사 ② 참이면 몸통 실행 ③ 다시 ①. 조건이 거짓이 되는 **순간이 아니라 다음 검사 때** 멈춰요.')],
  [T('반복 횟수를 세려면 카운터를 같이 돌려요. 물 한 잔 챌린지(2024) 유형: 하루 목표 2L 를 채울 때까지 몇 잔?'),
   C('goal = 2000      # 2L = 2000mL\ncup = 300\ndrank = 0\ncount = 0\nwhile drank < goal:\n    drank += cup\n    count += 1\nprint(count, drank)'),
   exam('단위가 섞여 나오면(L 와 mL) **먼저 하나로 통일**하세요. 2강의 시간 환산과 같은 원리예요.')]),
sh('위 물 마시기 코드에서 `cup = 250` 이면 `count` 는 얼마가 될까요?', 8, '250 × 8 = 2000. 8잔째에 drank 가 2000 이 되어 `2000 < 2000` 이 거짓 → 종료.'),
explain('break — 무한 반복에서 탈출',
  [T('`while True:` 는 끝없이 도는 반복이에요. 안에서 `break` 를 만나면 **즉시 반복을 끝내요**. 메뉴형·입력 반복 문제의 기본 틀이에요.'),
   trace('balance = 1000\nwhile True:\n    cmd = input()\n    if cmd == "종료":\n        break\n    if cmd == "입금":\n        balance += int(input())\n    elif cmd == "출금":\n        balance -= int(input())\nprint(balance)', '입출금 프로그램 (2025 4번 유형)', stdin='입금\n500\n출금\n300\n종료'),
   key('`break` 는 **가장 가까운 반복문 하나**만 빠져나와요.')],
  [T('UP AND DOWN(2023) 은 while + if/elif/else + 횟수 세기예요. 시험에서는 `random.randint(1, 100)` 으로 정답을 만들어요.'),
   C('answer = 37          # 시험에서는 random.randint(1, 100)\ntries = 0\nwhile True:\n    g = int(input())\n    tries += 1\n    if g < answer:\n        print("UP")\n    elif g > answer:\n        print("DOWN")\n    else:\n        print(f"정답! {tries}번 만에 맞혔어요")\n        break', stdin='50\n25\n37'),
   warn('`tries += 1` 의 위치가 중요해요. 정답을 맞힌 그 시도도 세야 하니 **비교하기 전에** 올려요.')]),
fill('도어락: 비밀번호가 맞으면 "열림", 3번 틀리면 "잠금"을 출력해요.', 'pw = "1234"\nfails = 0\nwhile fails ___ 3:\n    if input() == pw:\n        print("열림")\n        ___\n    fails += 1\nif fails == 3:\n    print("잠금")', ['<', 'break'], stdin='1111\n1234', expect='열림'),
outq('입력이 `1111`, `2222`, `3333` 일 때 위 도어락 코드의 출력은?', 'pw = "1234"\nfails = 0\nwhile fails < 3:\n    if input() == pw:\n        print("열림")\n        break\n    fails += 1\nif fails == 3:\n    print("잠금")', stdin='1111\n2222\n3333'),
explain('continue 와 무한 루프 디버깅',
  [T('`continue` 는 **아래 코드를 건너뛰고** 바로 다음 조건 검사로 가요.'),
   C('i = 0\nwhile i < 6:\n    i += 1\n    if i % 2 == 0:\n        continue\n    print(i, end=" ")'),
   T('짝수면 print 를 건너뛰어서 `1 3 5` 만 나와요.')],
  [T('2026 2번 기출 유형: 아래 코드는 **영원히 끝나지 않아요**. 왜일까요?'),
   cmp('무한 루프 ❌', 'i = 0\nwhile i < 6:\n    if i % 2 == 0:\n        continue\n    print(i)\n    i += 1', '고친 코드 ✅', 'i = 0\nwhile i < 6:\n    i += 1\n    if i % 2 == 0:\n        continue\n    print(i)', lb='i 가 0 일 때 continue → `i += 1` 을 **건너뜀** → i 는 계속 0', tones=('bad', 'good')),
   exam('서술 답안 틀: "**continue 가 실행되면 그 아래의 증가식을 건너뛰어 조건 변수가 변하지 않으므로** while 조건이 계속 참이 된다."')],
  [steps(['조건 변수 찾기', 'while 조건에 쓰인 변수(i)가 무엇인지'], ['변하는 곳 찾기', '그 변수가 몸통 어디에서 바뀌는지'], ['건너뛰는 길 찾기', 'continue 로 그 줄을 **안 지나가는 경로**가 있는지'], ['손으로 2~3바퀴', '값을 표로 적어 확인'])]),
spot('1부터 10까지 중 3의 배수를 **빼고** 출력하려는 코드예요. 무한 루프의 **원인이 되는 줄**(증가식의 위치가 잘못된 줄)을 고르세요.', 'n = 1\nwhile n <= 10:\n    if n % 3 == 0:\n        continue\n    print(n)\n    n += 1', 6, 'n 이 3 이 되면 continue 로 `n += 1` 을 건너뛰어 n 이 영원히 3 이에요. `n += 1` 을 if 앞으로 옮기거나, continue 전에 증가시켜야 해요.'),
explain('자릿수 반복 — 숫자 뒤집기·숫자 세기',
  [T('2강의 `% 10`, `// 10` 을 while 로 반복하면 **몇 자리 수든** 처리할 수 있어요.'),
   trace('n = 1234\nrev = 0\nwhile n > 0:\n    d = n % 10\n    rev = rev * 10 + d\n    n //= 10\nprint(rev)', '1234 → 4321'),
   key('`rev = rev * 10 + d` : 지금까지 만든 수를 한 칸 밀고 새 숫자를 붙여요.')],
  [T('"7이 몇 번 들어 있나"(2024, **count() 금지**)는 두 가지 방법이 있어요.'),
   tabs(['나머지로', '수학적으로 한 자리씩', 'n = 7727\ncnt = 0\nwhile n > 0:\n    if n % 10 == 7:\n        cnt += 1\n    n //= 10\nprint(cnt)'], ['문자열로', 'str 로 바꿔 글자를 순회', 'n = 7727\ncnt = 0\nfor c in str(n):\n    if c == "7":\n        cnt += 1\nprint(cnt)']),
   warn('`str(n).count("7")` 은 조건 위반이에요. **금지된 함수가 무엇인지** 조건에서 꼭 확인하세요.')]),
outq('출력 결과는?', 'n = 90210\ns = 0\nwhile n > 0:\n    s += n % 10\n    n //= 10\nprint(s)'),
essay('`while x != 1.0:` 처럼 "딱 그 값이 될 때까지" 도는 반복과, 정수 카운터 `while i < 10:` 반복 중 어느 쪽이 더 안전한지와 그 이유를 서술하세요. (힌트: 조건을 **건너뛰어 버리면** 어떻게 될까요?)', '`!=` 조건은 변수가 정확히 그 값이 되는 순간에만 멈추므로, 증가 폭 때문에 그 값을 건너뛰거나 실수 오차로 정확히 일치하지 않으면 무한 루프가 된다. `<` 같은 부등호 조건은 값을 지나치기만 해도 멈추므로 더 안전하다.', ['!= 는 정확히 일치할 때만 멈춘다고 썼다', '값을 건너뛰면(또는 오차가 있으면) 무한 루프가 된다고 썼다', '부등호 조건이 더 안전하다고 썼다'], '이 내용은 11강 float 오차에서 다시 만나요.'),
prac('기출 유사 ① — UP AND DOWN 기록지', '비밀 숫자 `ans` 가 첫 줄에, 플레이어가 부른 숫자들이 둘째 줄에 공백으로 주어져요. 부른 순서대로 판정을 한 줄씩 출력하세요.\n\n- 비밀 숫자보다 작으면 `UP`, 크면 `DOWN`\n- 맞히면 `정답! N번` (N 은 시도 횟수)을 출력하고 **그 뒤의 숫자는 무시**\n- 끝까지 못 맞히면 마지막 줄에 `실패` 출력',
  'ans = int(input())\ngs = list(map(int, input().split()))\ni = 0\nhit = False\nwhile i < len(gs):\n    g = gs[i]\n    i += 1\n    if g < ans:\n        print("UP")\n    elif g > ans:\n        print("DOWN")\n    else:\n        print(f"정답! {i}번")\n        hit = True\n        break\nif not hit:\n    print("실패")',
  ['37\n50 25 37 99', '10\n1 2 3', '77\n77', '50\n100 75 60 55 52 51 50 1 2', '1\n100 50 2', '64\n32 48 56 60 62 63 64'],
  starter='ans = int(input())\ngs = list(map(int, input().split()))\n', hints=['맞혔는지 기억하는 깃발 변수 `hit = False` 를 써 보세요.', '맞히면 `break`. 반복이 끝난 뒤 `if not hit:` 로 실패를 출력해요.']),
prac('기출 유사 ② — 도어락과 대기 시간', '도어락 비밀번호가 첫 줄에, 누른 번호들이 둘째 줄부터 한 줄에 하나씩 주어져요(마지막 줄은 `END`).\n\n[조건]\n- 맞으면 `열림` 을 출력하고 종료\n- 틀리면 `틀림 (대기 T초)` 를 출력. 대기 시간 T 는 첫 실패 때 2초이고 **실패할 때마다 2배**가 돼요\n- 4번 연속 틀리면 `틀림` 메시지 다음 줄에 `경보` 를 출력하고 종료\n- `END` 를 만나면 `취소` 를 출력하고 종료\n- 종료 후 마지막 줄에 `총 대기 N초` 출력',
  'pw = input()\nwait = 2\ntotal = 0\nfails = 0\nwhile True:\n    x = input()\n    if x == "END":\n        print("취소")\n        break\n    if x == pw:\n        print("열림")\n        break\n    fails += 1\n    print(f"틀림 (대기 {wait}초)")\n    total += wait\n    wait *= 2\n    if fails == 4:\n        print("경보")\n        break\nprint(f"총 대기 {total}초")',
  ['4812\n1111\n4812\nEND', '0000\n1\n2\n3\n4\n0000\nEND', '9999\n9999\nEND', '1234\nEND', '55\n5\n55\nEND', '7\n1\n2\n3\n7\nEND', '31\n13\n33\nEND'],
  hints=['`while True:` 안에서 END → 정답 → 오답 순서로 검사해요.', '대기 시간: 출력하고, 합계에 더하고, 그다음 `wait *= 2`', '시험에서는 실제로 `time.sleep(wait)` 으로 기다려요(10강).'], ex='상태 변수가 세 개예요: 실패 횟수 `fails`, 현재 대기 시간 `wait`, 누적 `total`. 각각 **언제 바뀌는지**를 정리하는 게 핵심이에요.'),
)

L6 = lesson('6강. 중첩 반복 — 패턴 출력과 구구단', 30,
'- 바깥 for 가 1번 돌 때 안쪽 for 는 **처음부터 끝까지** 다 돈다\n- 패턴 3단계: ① 줄 수(바깥) ② 한 줄의 개수를 i 의 식으로(안쪽) ③ 줄 끝 `print()`\n- `print(x, end="")` 로 옆으로, 빈 `print()` 로 줄바꿈\n- `(i + j) % 2` 체크무늬, `i == j or i + j == n - 1` X자\n- 일렬 번호 k → 행 `k // 열수`, 열 `k % 열수`',
review('🔁 4~5강 복습', [T('while 의 세 가지 도구를 확인해요.'), flip(['break', '반복을 **즉시 끝내요**'], ['continue', '아래를 건너뛰고 **다음 바퀴**로'], ['무한 루프의 단골 원인', 'continue 가 증가식을 건너뜀'])]),
outq('복습 — 출력 결과는?', 'n = 5\nwhile n > 0:\n    n -= 1\n    if n == 2:\n        continue\n    print(n, end=" ")', review=True),
explain('중첩 for 의 실행 순서',
  [T('반복문 안에 반복문을 넣으면, 바깥이 **한 번** 돌 때 안쪽은 **전부** 돌아요. 시계의 시침(바깥)과 분침(안쪽)과 같아요.'),
   trace('for i in range(1, 3):\n    for j in range(1, 4):\n        print(i, j)', 'i 와 j 가 바뀌는 순서를 보세요'),
   key('총 실행 횟수 = 바깥 횟수 × 안쪽 횟수 = 2 × 3 = 6')],
  [T('한 줄에 이어 찍으려면 `end=""`, 줄을 바꾸려면 안쪽 for 가 끝난 뒤 빈 `print()`.'),
   C('for i in range(3):\n    for j in range(5):\n        print("*", end="")\n    print()'),
   warn('`print()` 의 **들여쓰기 위치**가 핵심이에요. 안쪽 for 와 같은 깊이(바깥 for 의 몸통)여야 줄마다 한 번 실행돼요.')]),
sh('`for i in range(4):` 안에 `for j in range(i):` 가 있고 그 안에 `cnt += 1` 이 있어요. 끝난 뒤 `cnt` 는? (처음 0)', 6, '안쪽이 0 + 1 + 2 + 3 번 실행돼요.'),
explain('삼각형 패턴 — i 로 개수 정하기',
  [T('패턴 문제는 **"i번째 줄에 무엇이 몇 개인가"** 를 표로 적으면 풀려요.'),
   tabs(['직각삼각형', 'i번째 줄에 별 i개', 'n = 4\nfor i in range(1, n + 1):\n    print("*" * i)'], ['뒤집힌 삼각형', 'i번째 줄에 별 n-i+1개', 'n = 4\nfor i in range(n, 0, -1):\n    print("*" * i)'], ['오른쪽 정렬', '공백 n-i개 + 별 i개', 'n = 4\nfor i in range(1, n + 1):\n    print(" " * (n - i) + "*" * i)'], ['피라미드', '공백 n-i개 + 별 2i-1개', 'n = 4\nfor i in range(1, n + 1):\n    print(" " * (n - i) + "*" * (2 * i - 1))']),
   tip('`"*" * i` 문자열 반복을 쓰면 안쪽 for 가 필요 없어요. 단, 시험 조건이 "**중첩 for 를 사용**"이면 안쪽 for 로 써야 해요.')],
  [T('2025 6번: `random.randint` 로 뽑은 수만큼 직각삼각형 출력. 난수만 다를 뿐 구조는 같아요.'),
   C('import random\nn = random.randint(3, 6)\nprint("높이", n)\nfor i in range(1, n + 1):\n    for j in range(i):\n        print("*", end="")\n    print()')]),
outq('출력 결과를 그대로 써 보세요.', 'for i in range(1, 4):\n    for j in range(i):\n        print(i, end="")\n    print()'),
fill('높이 4인 **오른쪽 정렬** 직각삼각형이에요.', 'n = 4\nfor i in range(1, n + 1):\n    for j in range(___):\n        print(" ", end="")\n    for j in range(___):\n        print("*", end="")\n    print()', ['n - i', 'i'], expect='   *\n  **\n ***\n****'),
explain('구구단 — 한 줄에 여러 단',
  [T('2025 5번(15점): 구구단을 **한 줄에 3개 단씩, 역순으로** 출력. 중첩 구조를 정확히 잡아야 해요.'),
   steps(['무엇이 줄을 만드나?', '곱하는 수 j (1~9) 가 한 줄 → **바깥이 j**'], ['한 줄 안에는?', '단 i 가 옆으로 3개 → **안쪽이 i**'], ['묶음은?', '9·8·7단 / 6·5·4단 / 3·2단 처럼 3개씩 → 가장 바깥에 묶음 반복']),
   C('for j in range(1, 4):          # 곱하는 수 (줄)\n    for i in range(9, 6, -1):  # 단 (옆으로)\n        print(f"{i}x{j}={i * j:2d}", end="  ")\n    print()', '9·8·7단을 3줄만')],
  [T('세 묶음을 모두 출력하려면 한 겹 더 감싸요.'),
   C('for start in range(9, 1, -3):          # 9, 6, 3\n    for j in range(1, 10):\n        for i in range(start, max(start - 3, 1), -1):\n            print(f"{i}x{j}={i * j:2d}", end="  ")\n        print()\n    print()'),
   exam('"**어느 변수가 줄을 바꾸는가**"를 먼저 정하세요. 줄을 바꾸는 변수가 바깥, 옆으로 늘어나는 변수가 안쪽이에요.')]),
ch('구구단 2~4단을 **옆으로 나란히**(한 줄에 2x1 3x1 4x1) 출력하려면?', ['바깥: 단(2~4), 안쪽: 곱하는 수(1~9)', '바깥: 곱하는 수(1~9), 안쪽: 단(2~4)', '단과 곱하는 수를 한 for 에', 'while 만 사용'], 2, '한 줄에 "곱하는 수가 같은" 식들이 놓이니 곱하는 수가 바깥이에요.'),
explain('좌표 조건 패턴 — 체크무늬·X자·LED',
  [T('행 `i`, 열 `j` 의 **조건식**으로 무늬를 만들어요. 2023 1번이 `(n + j) % 2`, 2026 7번이 X자 LED 였어요.'),
   tabs(['체크무늬', '`(i + j) % 2 == 0` 인 칸만', 'n = 4\nfor i in range(n):\n    for j in range(n):\n        if (i + j) % 2 == 0:\n            print("#", end="")\n        else:\n            print(".", end="")\n    print()'], ['X자', '대각선 `i == j` 또는 반대 대각선 `i + j == n - 1`', 'n = 5\nfor i in range(n):\n    for j in range(n):\n        if i == j or i + j == n - 1:\n            print("X", end="")\n        else:\n            print(".", end="")\n    print()'], ['테두리', '첫/끝 행 또는 첫/끝 열', 'n = 4\nfor i in range(n):\n    for j in range(n):\n        if i in [0, n - 1] or j in [0, n - 1]:\n            print("#", end="")\n        else:\n            print(" ", end="")\n    print()'])],
  [T('LED 가 일렬 번호 0~24 로 주어지면 **몫과 나머지로 행·열**을 구해요 (5×5 판).'),
   C('k = 17\nrow, col = k // 5, k % 5\nprint(row, col)\nprint(row == col or row + col == 4)'),
   key('번호 k → 행 `k // 열의 수`, 열 `k % 열의 수`. 2강의 몫·나머지가 여기서 다시 쓰여요.')]),
outq('출력 결과를 그대로 써 보세요.', 'for i in range(3):\n    for j in range(4):\n        print((i + j) % 2, end="")\n    print()'),
sh('5×5 LED 판에서 번호 0~24 중 **X자 위에 있는 LED 의 개수**는?', 9, '두 대각선에 5개씩이고 가운데(12번)가 겹쳐서 5 + 5 - 1 = 9'),
prac('기출 유사 ① — 숫자 계단', '정수 `n` 이 주어지면 아래 규칙의 숫자 삼각형을 출력하세요.\n\n- i번째 줄(1≤i≤n)에는 i부터 시작해 **1씩 줄어드는** 수를 i개, 공백 없이 출력\n- 그 아래에 줄 수가 n-1, n-2, … 1 로 줄어드는 같은 무늬를 이어서 출력 (가운데 줄은 한 번만)\n\n[조건] ○ 중첩 반복문을 사용할 것',
  'n = int(input())\nfor i in list(range(1, n + 1)) + list(range(n - 1, 0, -1)):\n    for j in range(i, 0, -1):\n        print(j, end="")\n    print()', ['3', '1', '4', '2', '6', '9'],
  hints=['먼저 위쪽 절반(1~n줄)만 만들어 보세요: 안쪽은 `range(i, 0, -1)`', '아래쪽 절반은 바깥을 `range(n - 1, 0, -1)` 로 한 번 더 돌면 돼요.']),
prac('기출 유사 ② — 구구단 전광판', '시작 단 `a` 와 끝 단 `b` (2≤a≤b≤9)가 주어져요. a단부터 b단까지를 **큰 단부터 역순으로, 한 줄에 3개 단씩** 출력하세요.\n\n- 각 칸은 `단x수=곱` 형식, 곱은 **두 자리 폭 오른쪽 정렬**(`{:2d}`)\n- 칸 사이는 공백 2개, **줄 끝에는 공백 없음**\n- 묶음과 묶음 사이에 빈 줄 하나 (마지막 묶음 뒤에는 없음)',
  'a, b = map(int, input().split())\ndans = list(range(b, a - 1, -1))\ngroups = [dans[i:i + 3] for i in range(0, len(dans), 3)]\nfor gi in range(len(groups)):\n    for j in range(1, 10):\n        cells = []\n        for d in groups[gi]:\n            cells.append(f"{d}x{j}={d * j:2d}")\n        print("  ".join(cells))\n    if gi < len(groups) - 1:\n        print()',
  ['7 9', '2 9', '5 5', '3 6', '2 3', '4 9'],
  hints=['역순 단 목록: `range(b, a - 1, -1)`', '3개씩 묶기: 시작 단을 3씩 줄이며 `range(start, max(start - 3, a - 1), -1)`', '줄 끝 공백을 없애려면 한 줄의 칸들을 리스트에 모아 `"  ".join(cells)` 로 출력해요.'], ex='시험에서는 줄 끝 공백까지 보지는 않지만, 자동 채점과 실전 모두 **형식을 정확히** 맞추는 습관이 중요해요.'),
)

L7 = lesson('7강. 문자열 — 슬라이싱·메서드·ASCII', 35,
'- 인덱스 0부터, 음수는 뒤에서. `s[a:b:c]` 는 b **직전**까지\n- `s[::-1]` 뒤집기, 문자열은 **불변**(칸 수정 불가)\n- 메서드: `upper lower count find replace strip isdigit` — 원본은 안 바뀌고 **새 문자열**을 돌려줌\n- `find` 는 없으면 -1, `index` 는 없으면 ValueError\n- `ord("A")=65`, `ord("a")=97`, `ord("0")=48`, `chr(66)="B"`, `bin(65)="0b1000001"`',
review('🔁 5~6강 복습', [T('중첩 반복의 뼈대를 떠올려요.'), rev('별 삼각형에서 줄바꿈 `print()` 는 어디에 두나요?', '안쪽 for 가 **끝난 뒤**, 바깥 for 의 몸통에.'), rev('일렬 번호 k 의 행과 열(한 줄에 5칸)은?', code='k // 5, k % 5')]),
outq('복습 — 출력 결과는?', 'for i in range(3, 0, -1):\n    print("#" * i + "." * (3 - i))', review=True),
explain('인덱스와 슬라이싱',
  [T('문자열은 글자가 **칸칸이** 들어 있는 상자예요. 칸을 눌러 번호를 확인해 보세요.'),
   idx('s', 'PYNEST'),
   key('앞에서는 0부터, 뒤에서는 -1부터 세요. `s[len(s)]` 는 범위 밖이라 **IndexError**.')],
  [T('슬라이싱 `s[시작:끝:간격]` 은 **끝 직전까지** 잘라요. 숫자를 바꿔 보며 감을 잡으세요.'),
   slc('s', 'PYNEST', 1, 4),
   tip('빈칸으로 두면 "처음부터 / 끝까지"예요. `s[:3]` 앞 3글자, `s[3:]` 4번째부터 끝, `s[-2:]` 뒤 2글자.')],
  [T('간격을 주면 건너뛰거나 뒤집을 수 있어요.'),
   slc('s', 'ABCDEFGH', '', '', -1),
   flip(['s[::2]', '짝수 번째 칸: 한 칸씩 건너뛰기'], ['s[::-1]', '전체 뒤집기 — 회문 검사에 써요'], ['s[1:-1]', '양 끝 한 글자씩 빼기'], ['s[5:2]', '빈 문자열 `""` — 오류가 아니에요'])]),
outq('출력 결과는?', 's = "GWANGJU"\nprint(s[0], s[-1], s[2:5])\nprint(s[::-1])\nprint(s[::3], s[-3:])'),
match('`s = "abcdef"` 일 때 식과 결과를 이어 보세요.', [['s[1:3]', 'bc'], ['s[:2]', 'ab'], ['s[-2:]', 'ef'], ['s[::2]', 'ace'], ['s[4:1:-1]', 'edc']]),
explain('문자열은 불변 · 순회 · in',
  [T('문자열의 칸은 **바꿀 수 없어요**(불변). 바꾸려면 새 문자열을 만들어야 해요.'),
   cmp('오류 ❌', 's = "cat"\ns[0] = "b"', '새로 만들기 ✅', 's = "cat"\ns = "b" + s[1:]\nprint(s)', lb='TypeError — 문자열은 칸에 대입할 수 없어요', tones=('bad', 'good')),
   C('pw = "ab12cd"\ncnt = 0\nfor c in pw:\n    if c.isdigit():\n        cnt += 1\nprint(cnt)\nprint("12" in pw, "21" in pw)', '글자 하나씩 순회, in 으로 포함 검사')],
  [T('주민번호·전화번호 **마스킹**은 슬라이싱 + 반복으로 만들어요.'),
   C('num = "010-1234-5678"\nprint(num[:4] + "****" + num[-5:])\nname = "홍길동"\nprint(name[0] + "*" * (len(name) - 1))')]),
fill('문자열을 뒤집어 **회문**(거꾸로 읽어도 같은 말)인지 검사해요.', 's = "level"\nif s == s[___]:\n    print("회문")\nelse:\n    print("아님")', ['::-1'], expect='회문'),
explain('꼭 아는 메서드',
  [T('메서드는 `문자열.이름()` 으로 써요. **원본은 그대로 두고 결과를 돌려줘요**.'),
   tabs(['대소문자', '', 's = "PyNest"\nprint(s.upper(), s.lower())\nprint(s)   # 원본은 그대로'], ['count · find', 'count 는 개수, find 는 **처음 나오는 위치**(없으면 -1)', 's = "banana"\nprint(s.count("a"), s.find("n"), s.find("z"))'], ['replace · strip', '바꾸기, 양끝 공백 제거', 's = "  a-b-c  "\nprint(s.strip().replace("-", "+"))'], ['검사', '`isdigit()` 전부 숫자? `isalpha()` 전부 글자?', 'print("2024".isdigit(), "20a4".isdigit(), "abc".isalpha())']),
   warn('`s.upper()` 만 쓰고 저장을 안 하면 아무 일도 안 일어나요. `s = s.upper()` 로 받아야 해요.')],
  [T('`find` 와 `index` 의 차이는 2026 4번에 나왔어요.'),
   cmp('find — 없으면 -1', 's = "hello"\nprint(s.find("z"))', 'index — 없으면 오류', 's = "hello"\nprint(s.index("z"))', rb='ValueError: substring not found', tones=('good', 'bad')),
   exam('"오류 없이 안전하게 찾으려면?" → `find` 를 쓰거나, `if "z" in s:` 로 **먼저 검사**한 뒤 `index` 를 써요.')]),
bucket('`s = "Hello"` 일 때 결과를 나눠 보세요.', ['-1', '오류', '그 외의 값'], [['s.find("x")', 1], ['s.index("x")', 2], ['s.find("l")', 3], ['s[5]', 2], ['s[5:]', 3], ['s.count("x")', 3]], '`s.find("l")` 은 2, `s[5:]` 는 빈 문자열, `s.count("x")` 는 0 이에요.'),
spot('입력받은 아이디를 모두 소문자로 바꿔 비교하려는 코드예요. **효과가 없는 줄**을 고르세요.', 'uid = "PyNest"\nuid.lower()\nif uid == "pynest":\n    print("ok")\nelse:\n    print("no")', 2, '`uid.lower()` 의 결과를 저장하지 않아 uid 는 그대로 "PyNest" 예요. `uid = uid.lower()` 로 써야 해요.'),
explain('ASCII — ord · chr · bin',
  [T('컴퓨터는 글자를 **숫자(코드)** 로 저장해요. 2026 10번에 처음 나왔어요.'),
   C('print(ord("A"), ord("a"), ord("0"))\nprint(chr(65), chr(97 + 3))\nprint(bin(65), bin(ord("a")))'),
   flip(['ord("A")', '65'], ['ord("a")', '97 (대문자 + 32)'], ['ord("0")', '48'], ['chr(ord("A") + 1)', '"B"'], ['bin(5)', '"0b101" — 문자열이에요'])],
  [T('코드 값의 **차이**를 이용하면 글자를 밀거나(암호) 순서를 구할 수 있어요.'),
   trace('word = "abz"\nout = ""\nfor c in word:\n    k = (ord(c) - ord("a") + 1) % 26\n    out += chr(ord("a") + k)\nprint(out)', '한 글자씩 뒤로 밀기 (z 다음은 a)'),
   key('`ord(c) - ord("a")` 는 알파벳 순서(0~25). `% 26` 으로 z 다음에 a 로 돌아가요.')]),
sh('`chr(ord("D") + 32)` 의 결과는?', 'd', '대문자에 32를 더하면 같은 글자의 소문자예요.'),
essay('`s = "python"` 에서 첫 글자를 대문자로 바꾸려고 `s[0] = "P"` 를 실행하면 오류가 나요. **오류의 종류와 이유**, 그리고 **올바른 방법**을 서술하세요.', 'TypeError 가 발생한다. 문자열은 불변(immutable) 자료형이라 인덱스로 특정 칸의 값을 바꿀 수 없기 때문이다. `s = "P" + s[1:]` 처럼 슬라이싱과 연결로 새 문자열을 만들어 다시 저장해야 한다.', ['TypeError 라고 썼다', '문자열은 불변이라 칸을 바꿀 수 없다고 썼다', '슬라이싱 등으로 새 문자열을 만드는 방법을 썼다']),
prac('기출 유사 ① — 7은 몇 번?', '정수 `a`, `b` (1≤a≤b≤100000)가 주어져요. a부터 b까지의 모든 수에 숫자 **7** 이 총 몇 번 쓰였는지 출력하세요. (예: 77 에는 2번)\n\n[조건] ○ `count()` 메서드를 사용하지 말 것',
  'a, b = map(int, input().split())\ncnt = 0\nfor n in range(a, b + 1):\n    for c in str(n):\n        if c == "7":\n            cnt += 1\nprint(cnt)', ['1 100', '70 80', '1 6', '7 7', '777 777', '1 10000', '69999 70010'],
  hints=['수를 `str(n)` 으로 바꿔 글자를 하나씩 순회해요.', '또는 `n % 10 == 7` 과 `n //= 10` 으로 자릿수를 떼도 돼요.']),
prac('기출 유사 ② — 허수 비밀번호', '도어락에 **허수 기능**이 있어요. 진짜 비밀번호 앞뒤에 아무 숫자나 붙여 눌러도, 누른 숫자열 안에 진짜 비밀번호가 **연속으로** 들어 있으면 열려요.\n\n첫 줄에 비밀번호 `pw`, 둘째 줄에 누른 숫자열 `s` 가 주어져요.\n\n- 포함되면 `열림 K` (K 는 비밀번호가 **처음** 시작되는 위치, 1부터 셈)\n- 아니면 `실패`\n\n[조건] ○ `in`, `find`, `index` 를 쓰지 말고 **슬라이싱과 반복문**으로 찾을 것 ○ 찾으면 즉시 반복을 끝낼 것',
  'pw = input()\ns = input()\nfound = 0\nfor i in range(len(s) - len(pw) + 1):\n    if s[i:i + len(pw)] == pw:\n        found = i + 1\n        break\nif found:\n    print("열림", found)\nelse:\n    print("실패")',
  ['1234\n9912345', '1234\n12431243', '77\n1777', '5\n5', '123\n12', '808\n98080808', '4321\n1234321', '99\n123456789'],
  hints=['시작 위치 i 에서 `s[i:i + len(pw)]` 를 잘라 pw 와 비교해요.', 'i 는 `range(len(s) - len(pw) + 1)` 까지만 돌면 돼요.', '찾았는지 기억하는 변수 + `break`'], ex='2026 8번(15점) 유형이에요. "슬라이싱으로 길이만큼 잘라 비교 + 불리언(깃발) + break" 세 가지가 채점 포인트였어요.'),
)
